from pathlib import Path
from docx import Document
from docx.shared import Pt
import json
b=Path('/workspace/temp/presentation/v9');notes=json.loads((b/'speaker-notes.json').read_text())
cn=[
('项目介绍','藤织荫冠将爬藤植物与树形支架结合，为行人提供遮荫。我们小组的工作涵盖参数化几何设计、材料与施工选择，以及遮荫分析。下方姓名对应各成员的任务分工。接下来，我们将介绍设计决策及其依据。','首先介绍最终几何形态及其图纸中的测量定义。'),
('几何参数与图纸','最终模型总高约3.48米，平面外缘范围约6.22米×6.66米，最大水平外缘跨度约6.91米。对于这些弯曲支撑杆，我们将倾角定义为杆件两端点连线相对水平面的夹角。配套图纸说明了这一定义及测得的角度范围。','接下来，说明这些结构特征与环境改善潜力之间的联系。'),
('结构与冷却潜力','冠层和叶片在太阳直射到达人体与地面之前对其进行遮挡。太阳射线箭头表示我们在光学情景中进行了量化的作用路径。蓝色箭头表示开放侧面可能保留的空气流动路径，并不是模拟得到的通风改善。植物水分的虚线箭头表示可能发生的蒸散作用，其效果取决于植物健康与供水条件。更密集的叶片也可能增加气流阻力。','材料配置需要对应不同的结构作用。'),
('材料分区与用量','模型取量得到12根落地支撑杆和47根冠层杆件，中心线总长为288.66米。我们拟采用外径80毫米、壁厚4毫米的钢管作为支撑，冠层则采用实心工程竹。这是一项材料配置方案，并不证明任一区域的结构安全已经得到验证。','筛选表展示了输入数据，接下来需要解释如何使用这些数据作出选择。'),
('材料筛选数据','这些是初步材料筛选输入。费用列均按相同的全部杆件长度计算，并不是最终采用的单元预算。钢材的名义抗弯承载力明显更高。冠层拟采用工程竹，但其刚度、防护处理和具体产品依据仍十分关键。原竹参考费用较低，也不能消除其性能离散与维护问题。','这些输入支持采用带有前提条件的混合材料策略。'),
('为什么选择钢支撑与工程竹冠层','工作簿将材料筛选与结构可行性门槛结合起来。钢材用于承受压力及风致弯曲的支撑杆。冠层结合成本和碳排输入采用竹材，但挠度校核表同时要求验证节点转动刚度。下方卡片概括了五项材料选择准则。杆件材料投入的节省，并不能直接证明整个单元总价更低。','下一项校核将说明，为什么冠层刚度会使连接节点变得重要。'),
('节点与挠度','对于同一个6.65米竹杆简化计算，简支条件下的挠度约为100.5毫米，理想两端固接条件下约为20.1毫米。采用的控制目标是33.25毫米，在图中位于两者之间。这说明需要进一步研究节点提供转动约束的能力。拟议节点并未证明已经具有这种约束能力，单根构件校核也不等于整体框架验算。','拟议节点在预算中也占有较大的费用。'),
('成本分析','初步总价约为51,676元，材料费约占59%，其他类别包括加工、安装和养护。在材料费中，12个拟议节点合计12,000元，高于主体钢构件的费用。右侧构件费用表只是总价的一部分，不能再次加到总价上。','接下来介绍碳排与维护。'),
('碳排与维护','主体杆件和配重构成了当前碳排估算的大部分。配重约占39%，因此基础方案同样重要。这里展示的是采用的估算，而不是已经核验的生命周期评价结果。户外使用还需要钢材涂层维护、竹材防护处理和连接检查。产品碳因子以及实际节点材料的计入情况仍需核实。','植物选择也带来了另一组需要考虑的条件。'),
('植物选择','工作簿选用2株爬山虎和1株使君子，筛选时考虑季节性落叶与杆件攀附匹配。爬山虎通过带吸盘的卷须攀附，使君子缠绕，凌霄通过气生根攀附。前两种的工作簿参考湿重范围均为每平方米10至18千克。简化梁计算采用18，明确取自爬山虎范围的上限。这些是尚未核实原始来源的参考输入，而不是实测荷载。备选凌霄的范围上限达到25，因此替换时需要重新核查荷载。','接下来介绍用于评价遮荫的光学方法。'),
('两类遮荫指标','第一个指标衡量理想连续叶面包络在目标区上的阴影重合。第二个指标包含裸架阴影、假设的叶簇、两者的重叠及叶片透射。我们用第一个指标比较日内与不同太阳季节条件下的结果，用第二个指标比较结构参数和植物覆盖情景。两者采用相同目标区，但百分比不能互换使用，也都不是温降。','首先从完整时段理解理想遮荫结果。'),
('时段与太阳季节结果','动画按原有夏至采样，从太阳时9点播放到15点。9点和15点的重合率约为47%，正午接近99%。曲线保留完整时序及春秋分太阳条件下的情景，时段均值分别约为75%和50%。正午峰值不能代表整个使用时段：布置座椅时还需检查上午和下午的日照暴露。春秋分比较改变的是太阳条件，而不是植物叶片覆盖。','随后，我们每次改变一个几何控制参数。'),
('结构参数对遮荫的影响','七个情景分别改变扩展系数、上部高度控制或圆角系数，每次只改变一项。在50%覆盖条件下，扩大冠层使平均等效直射遮挡率从52.3%变为66.1%，表中也保留了其他控制参数的结果。原报告提醒，同样的覆盖比例下，更大的冠层需要更多种植覆盖面积。这些遮荫比较没有保持投入相等，也没有确定最优方案。','接下来固定结构，改变植物覆盖。'),
('覆盖率与叶片分布','这条曲线区分了平面覆盖率和平均等效直射遮挡率。即使叶片覆盖为零，裸架本身也会产生遮荫。在这些情景中，覆盖率从80%增加到95%，平均等效直射遮挡率仅增加约2.8个百分点。另外，在相同50%覆盖率下，三种分布在正午产生的等效直射遮挡率为62.6%到77.5%。因此，原报告要求我们同时考虑叶片位置和使用时段的座椅布置，而不只是覆盖率。','随后，将移动的阴影与公共空间使用联系起来。'),
('实际使用与布置','动画保持覆盖率固定，仅改变太阳位置。座椅应按实际使用时段进行检查，同时为通行、配重、根区和维护留出空间。下一步验证是在真实场地同步开展冠下与无遮挡区域的环境观测。目前的分析尚未确定净可用遮荫地面面积，也没有实测热舒适改善结果。','最后一个设计环节是施工组织。'),
('模块化施工','方案将系统分为冠层杆件、支撑杆、连接、配重基础和种植模块。编号和预拼装有助于现场组织。不过，较重的配重决定了吊装要求，套管灌浆节点也需要养护和检查。14人工日是劳务投入估算，不是日历工期。不能将该系统表述为完全干式装配或无损可逆拆装。','最后总结我们的交付成果及下一步核查。'),
('总结','小组交付了参数化形态与取量、拟议的材料和建造策略，以及可复算的遮荫情景。补充材料包括7个参数模型、5档覆盖状态和1,750行时步结果。这些成果使设计决策能够追溯到依据。下一步需要核查产品数据、节点性能、植物适生性和真实场地表现。谢谢大家。','欢迎提问。'),
('参考文献与问答','本页为参考文献与问答页，不属于计划中的正文讲述。它列出文献线索及项目依据。具体产品参数和标准仍需核对原始来源。','根据提问返回相应的结果页。')]
D=Document();D.styles['Normal'].font.name='Noto Sans';D.styles['Normal'].font.size=Pt(11);D.add_heading('VineWeave Canopy — V9 Bilingual Script',0)
intro='对应V9的18页。第1—17页为正文，第18页为参考与问答提示。中文用于理解和练习；课堂英文展示不需将两种语言都读出。英文口述词数与时间估计见完整Presenter Guide。来源依据和答辩备忘见完整Presenter Guide。'
D.add_paragraph(intro);md=['# V9 中英文对照讲稿','',intro,'','[完整讲稿：来源与答辩备忘](Presenter-Guide-v9.md)','']
for n,(title,body,transition) in zip(notes,cn):
 heading=f"{n['slide']:02d}｜{title}";D.add_heading(heading,1);md+=['## '+heading,'']
 for label,text in [('English',n['script']),('中文',body),('Transition',n['transition']),('过渡',transition)]:
  p=D.add_paragraph();p.add_run(label+'：').bold=True;p.add_run(text);md += ['**'+label+'**', '',text,'']
D.save(b/'Bilingual-Script-v9.docx');(b/'Bilingual-Script-v9.md').write_text('\n'.join(md))
assert len(cn)==len(notes)==18
print('Created bilingual scripts: 18 pages.')
